#!/bin/sh
# A/B: WebKit built for cortex-a9 (buildroot-nc4 default) vs cortex-a55 (the C1's cores),
# same sources and patches; the lib is swapped on the TV before each half of a round.
set -e
python3 bench/tvtelnet.py "$TV_HOST" "luna-send -n 1 luna://com.webos.applicationManager/closeByAppId '{\"id\":\"com.viiees.browser\"}' >/dev/null; sleep 2; cp /media/developer/apps/usr/palm/applications/com.viiees.browser/lib/libWPEWebKit.a9p13 /media/developer/apps/usr/palm/applications/com.viiees.browser/lib/libWPEWebKit-2.0.so.1 && md5sum /media/developer/apps/usr/palm/applications/com.viiees.browser/lib/libWPEWebKit-2.0.so.1"
python3 ./bench/bench.py run --label p13-a9 micro load-wiki wheel-wiki raf-wiki speedometer cold-youtube wheel-youtube
